class Solution { public boolean leafSimilar(TreeNode root1,TreeNode root2){List<Integer> first=new ArrayList<>(),second=new ArrayList<>();collect(root1,first);collect(root2,second);return first.equals(second);}private void collect(TreeNode node,List<Integer> leaves){if(node==null)return;if(node.left==null&&node.right==null){leaves.add(node.val);return;}collect(node.left,leaves);collect(node.right,leaves);} }
